    34|const demoLogin = async (req, res) => {
    35|    const { email, password } = req.body || {};
    36|    if (!password) return res.status(400).json({ message: 'password not provided' });
    37|    if (!email) return res.status(400).json({ message: 'email not provided' });
    38|
    39|    const user = demoUsers.get(email.toLowerCase()) || publicUser(req.body);
    40|    return res.status(200).json({
    41|        message: 'user logged in',
